// a small context menu next to a button; fixed, so a card that clips its content never cuts it off
function cmenu(btn,html,cls){document.querySelectorAll("[data-open]").forEach(x=>delete x.dataset.open);btn.dataset.open="1";const m=document.createElement("div");m.className="cmenu "+(cls||"");m.setAttribute("role","menu");m.innerHTML=html;document.body.appendChild(m);
const r0=btn.getBoundingClientRect(),an=btn.closest("[data-menuanchor]"),r=an?an.getBoundingClientRect():r0,h=m.offsetHeight,w=m.offsetWidth,up=r.bottom+6+h>innerHeight-8&&r.top-6-h>8;m.style.top=(up?r.top-6-h:r.bottom+6)+"px";const rtl=document.documentElement.classList.contains("he");if(btn.dataset.menualign=="start"){const lx=Math.max(8,Math.min(rtl?r.right-w:r.left,innerWidth-w-8));m.style.left=lx+"px"}else{const x=Math.max(8,Math.min(rtl?r.left:innerWidth-r.right,innerWidth-w-8));m.style[rtl?"left":"right"]=x+"px"}m.style.maxHeight=Math.max(120,Math.min(up?r.top-14:innerHeight-r.bottom-14,360))+"px"}
addEventListener("scroll",e=>{if(e.target.closest&&e.target.closest(".cmenu"))return;document.querySelectorAll(".cmenu").forEach(m=>m.remove())},{passive:true,capture:true});
